// child order/axis (VStack stacks downward, HStack flows rightward).
double pathland_qt_layer_widget_position(uint32_t id, uint32_t which) {
    QQuickItem *item = findWidget(id);
    if (!item) {
        return -1;
    }
    return which == 0 ? item->x() : item->y();
