            Command::insert_child(CONTENT_ITEM, 20, u32::MAX),
            Command::set_property(20, 0x0002, value_type::F32, 1.0f32.to_bits()), // ALIGNMENT=Center
            Command::create_node(21, 0x01),                                       // TEXT
            Command::insert_child(20, 21, u32::MAX),
