int deriveFitIndex(const std::vector<double> &thresholds, double width) {
    if (thresholds.empty()) {
        return 0;
    }
    int index = 0;
    for (size_t i = 0; i < thresholds.size(); ++i) {
        if (thresholds[i] <= width) {
            index = static_cast<int>(i);
        } else {
            break;
        }
    }
    return index;
}

