    pub kind: u8,
    pub node_id: u32,
    pub x: f32,
    pub y: f32,
    pub value: f32,
    pub str_len: u32,
    pub str_: *const c_char,
    /// KEY_DOWN/KEY_UP payload: platform key code + modifier bitmask + repeat.
    pub key_code: u16,
    pub modifiers: u8,
    pub repeat: u8,
}

