            1,
            "MEDIA_MUTED -> AudioOutput.muted"
        );
        assert_eq!(
            pathland_qt_layer_media_loops(2),
            -1,
            "MEDIA_LOOP -> loops = -1 (infinite)"
        );
        assert!(
            (pathland_qt_layer_media_rate(2) - 1.5).abs() < 0.001,
            "MEDIA_RATE -> playbackRate"
        );
    });
}

