// ZStack 2D alignment codes (spec/PRIMITIVES.md §ZStack): the low nibble selects
// a horizontal (0=start,1=center,2=end) and vertical component.
static const int kZAlignH[9] = {0, 1, 2, 1, 1, 0, 2, 2, 0};
static const int kZAlignV[9] = {0, 1, 2, 0, 2, 1, 1, 0, 2};

// Position one ZStack child by the stack's 2D ALIGNMENT (position only — a child
// keeps its own size; a FILL/greedy child is already anchored edge-to-edge).
void applyZStackAlignment(uint32_t parentId, uint32_t childId) {
    QQuickItem *parent = findWidget(parentId);
    QQuickItem *child = findWidget(childId);
    if (!parent || !child || child->parentItem() != parent) {
        return;
    }
    QObject *anchors = child->property("anchors").value<QObject *>();
    if (!anchors) {
        return;
    }
    if (anchors->property("fill").value<QQuickItem *>()) {
        return; // fills both axes (already stretched) — alignment doesn't apply
    }
    int code = 0;
    auto it = g.stack_align.find(parentId);
    if (it != g.stack_align.end()) {
        const float raw = f32(it->second);
        const int c = (std::isfinite(raw) && std::floor(raw) == raw && raw >= 0.0f && raw <= 8.0f)
                          ? static_cast<int>(raw)
                          : static_cast<int>(it->second & 0xFF);
        code = (c >= 0 && c <= 8) ? c : 0;
    }
    const int h = kZAlignH[code];
    const int v = kZAlignV[code];
    const bool fillW =
        g.width_hint.count(childId) && g.width_hint[childId] == PL_SIZE_FILL;
    const bool fillH =
        g.height_hint.count(childId) && g.height_hint[childId] == PL_SIZE_FILL;
    auto clear = [&](const char *a) {
        anchors->setProperty(a, QVariant::fromValue<QQuickItem *>(nullptr));
    };
    if (!fillW) {
        clear("left");
        clear("right");
        clear("horizontalCenter");
        const char *a = h == 0 ? "left" : (h == 1 ? "horizontalCenter" : "right");
        anchors->setProperty(a, QVariant::fromValue(parent));
    }
    if (!fillH) {
        clear("top");
        clear("bottom");
        clear("verticalCenter");
        const char *a = v == 0 ? "top" : (v == 1 ? "verticalCenter" : "bottom");
        anchors->setProperty(a, QVariant::fromValue(parent));
    }
}

void recomputeLayout() {
    for (auto &kv : g.components) {
        const uint32_t parentId = kv.first;
        if (!isContainer(parentId) || g.nav_slots.count(parentId)) {
            continue; // promoted nav slots have no Column/RowLayout
        }
        QQuickItem *parent = findWidget(parentId);
        if (!parent || !layoutOf(parent)) {
            continue;
        }
        auto ch = g.children_of.find(parentId);
        if (ch == g.children_of.end()) {
            continue;
        }
        for (uint32_t childId : ch->second) {
            auto cit = g.components.find(childId);
            if (cit != g.components.end() && isNonVisual(cit->second)) {
                continue;
            }
            applyChildAxes(parentId, childId, findWidget(childId));
        }
    }
    // ZStack children share one box; position each by the stack's 2D ALIGNMENT.
    for (auto &kv : g.components) {
        if (kv.second != PL_COMP_ZSTACK) {
            continue;
        }
        auto ch = g.children_of.find(kv.first);
        if (ch == g.children_of.end()) {
            continue;
        }
        for (uint32_t childId : ch->second) {
            auto cit = g.components.find(childId);
            if (cit != g.components.end() && isNonVisual(cit->second)) {
                continue;
            }
            applyZStackAlignment(kv.first, childId);
        }
    }
}

/// ZStack ALIGNMENT positions each child on both axes with the spec's 2D
/// code (0..8), never resizing it (spec/PRIMITIVES.md §ZStack).
#[test]
fn zstack_alignment_positions_children_on_both_axes() {
    with_qt(|| unsafe {
        let cmds = [
            Command::create_node(1, component_type::VSTACK),
            Command::insert_child(CONTENT_ITEM, 1, u32::MAX),
            Command::create_node(2, component_type::ZSTACK),
            Command::insert_child(1, 2, u32::MAX),
            Command::set_property(2, property_id::WIDTH, value_type::F32, (-1.0f32).to_bits()),
            Command::set_property(2, property_id::HEIGHT, value_type::F32, (-1.0f32).to_bits()),
            Command::create_node(3, component_type::TEXT),
            Command::insert_child(2, 3, u32::MAX),
            Command::set_property(3, property_id::WIDTH, value_type::F32, 20.0f32.to_bits()),
            Command::set_property(3, property_id::HEIGHT, value_type::F32, 20.0f32.to_bits()),
            Command::set_text(3, "x"),
        ];
        pathland_qt_layer_apply(cmds.as_ptr(), cmds.len() as u32);
        assert_eq!(pathland_qt_layer_render_once(), 1);

        let zw = pathland_qt_layer_widget_size(2, 0);
        let zh = pathland_qt_layer_widget_size(2, 1);
        let cw = pathland_qt_layer_widget_size(3, 0);
        let ch = pathland_qt_layer_widget_size(3, 1);
        assert!(zw > 100.0 && zh > 100.0, "the ZStack fills the window (got {zw}x{zh})");

        // (code, horizontal 0/1/2, vertical 0/1/2)
        let cases = [
            (0u32, 0u32, 0u32),
            (1, 1, 1),
            (2, 2, 2),
            (3, 1, 0),
            (4, 1, 2),
            (5, 0, 1),
            (6, 2, 1),
            (7, 2, 0),
            (8, 0, 2),
        ];
        for (code, h, v) in cases {
            let set = [Command::set_property(
                2,
                property_id::ALIGNMENT,
                value_type::F32,
                (code as f32).to_bits(),
            )];
            pathland_qt_layer_apply(set.as_ptr(), set.len() as u32);
            assert_eq!(pathland_qt_layer_render_once(), 1);

            let want_x = match h {
                0 => 0.0,
                1 => (zw - cw) / 2.0,
                _ => zw - cw,
            };
            let want_y = match v {
                0 => 0.0,
                1 => (zh - ch) / 2.0,
                _ => zh - ch,
            };
            let x = pathland_qt_layer_widget_position(3, 0);
            let y = pathland_qt_layer_widget_position(3, 1);
            assert!(
                (x - want_x).abs() < 0.5 && (y - want_y).abs() < 0.5,
                "code {code} places the child at ({want_x},{want_y}), got ({x},{y})"
            );
            // Position-only: the child keeps its own size.
            assert!((pathland_qt_layer_widget_size(3, 0) - cw).abs() < 0.5);
            assert!((pathland_qt_layer_widget_size(3, 1) - ch).abs() < 0.5);
        }
    });
}

