            "second child flows right of the first (got x3={x3}, x4={x4})"
        );
        assert!(
            (y4 - y3).abs() < 0.5,
            "default stretch aligns children on the top (y3={y3}, y4={y4})"
        );
        assert!(
            (x4 - (x3 + w3) - 10.0).abs() < 0.5,
