fn explicit_fill_stretches_cross_axis() {
    with_qt(|| unsafe {
        let cmds = [
            Command::create_node(1, component_type::HSTACK),
            Command::insert_child(0, 1, u32::MAX),
            Command::create_node(2, component_type::TEXT),
