/// SCROLLVIEW is layout-greedy on both axes by default: as a stack child it
/// takes the layout fill on both axes; as a non-layout (ZStack) child it is
/// anchored edge-to-edge (spec/PRIMITIVES.md §ScrollView).
#[test]
fn scroll_view_fills_by_default() {
    with_qt(|| unsafe {
        // As a stack child: Layout.fillWidth/fillHeight + the full box.
        let cmds = [
            Command::create_node(1, component_type::ZSTACK),
            Command::insert_child(CONTENT_ITEM, 1, u32::MAX),
            Command::create_node(2, component_type::VSTACK),
            Command::insert_child(1, 2, u32::MAX),
            Command::set_property(2, property_id::WIDTH, value_type::F32, 300.0f32.to_bits()),
            Command::set_property(2, property_id::HEIGHT, value_type::F32, 200.0f32.to_bits()),
            Command::create_node(3, component_type::SCROLLVIEW),
            Command::insert_child(2, 3, u32::MAX),
            // As a non-layout (ZStack) child: anchored fill.
            Command::create_node(10, component_type::ZSTACK),
            Command::insert_child(CONTENT_ITEM, 10, u32::MAX),
            Command::create_node(11, component_type::SCROLLVIEW),
            Command::insert_child(10, 11, u32::MAX),
        ];
        pathland_qt_layer_apply(cmds.as_ptr(), cmds.len() as u32);
        assert_eq!(pathland_qt_layer_render_once(), 1);

        assert_eq!(pathland_qt_layer_widget_fill(3, 0), 1, "fills the stack width");
        assert_eq!(pathland_qt_layer_widget_fill(3, 1), 1, "fills the stack height");
        assert!((pathland_qt_layer_widget_size(3, 0) - 300.0).abs() < 1.0, "stack child width");
        assert!((pathland_qt_layer_widget_size(3, 1) - 200.0).abs() < 1.0, "stack child height");

        // A non-layout (ZStack) child is anchored edge-to-edge to its parent.
        assert!(
            (pathland_qt_layer_widget_size(11, 0) - 420.0).abs() < 1.0,
            "the non-layout child fills the ZStack width (got {})",
            pathland_qt_layer_widget_size(11, 0)
        );
        assert!(
            (pathland_qt_layer_widget_size(11, 1) - 220.0).abs() < 1.0,
            "the non-layout child fills the ZStack height (got {})",
            pathland_qt_layer_widget_size(11, 1)
        );
    });
}

