// Bridge; Rust re-resolves design tokens and re-applies (spec/TOKENS.md).
void reportScheme() {
    if (!g.app || !g.bridge) {
        return;
    }
    const bool dark = g.app->styleHints()->colorScheme() == Qt::ColorScheme::Dark;
    g.bridge->schemeChanged(dark ? 1 : 0);
}

