/// QGuiApplication is process-global: serialize every Qt-touching test and
/// initialize it **once per process**. Destroying and re-creating the GUI
/// application between tests is unsupported (Qt allows one per process) and
/// crashes on Linux/Qt 6.4; `reset()` isolates the test state instead.
static QT_LOCK: Mutex<()> = Mutex::new(());
static QT_INIT: Once = Once::new();

fn with_qt(f: impl FnOnce()) {
    let _guard = QT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    std::env::set_var("QT_QPA_PLATFORM", "offscreen");
    std::env::set_var("QT_QUICK_BACKEND", "software");
    QT_INIT.call_once(|| unsafe {
        assert_eq!(
            pathland_qt_layer_init(noop_wake, noop_tick, noop_event, std::ptr::null_mut()),
            0
        );
    });
    unsafe {
        pathland_qt_layer_reset(); // isolate test state (counters + widgets)
        f();
    }
}

